CREATE TABLE IF NOT EXISTS schema_version (version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('client','admin','superadmin')), village_id TEXT, disabled INTEGER NOT NULL DEFAULT 0, force_password_change INTEGER NOT NULL DEFAULT 1, failed_logins INTEGER NOT NULL DEFAULT 0, locked_until REAL NOT NULL DEFAULT 0, last_login REAL);
CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY, user_id INTEGER, action TEXT NOT NULL, resource TEXT NOT NULL, created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS villages (id TEXT PRIMARY KEY, name TEXT NOT NULL, phc TEXT NOT NULL DEFAULT '', demo INTEGER NOT NULL DEFAULT 1, created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS facilities (id INTEGER PRIMARY KEY, name TEXT NOT NULL, village_id TEXT, type TEXT NOT NULL, contact TEXT NOT NULL DEFAULT '', directions_url TEXT NOT NULL DEFAULT '', demo INTEGER NOT NULL DEFAULT 1, created REAL NOT NULL, user_id INTEGER);
CREATE TABLE IF NOT EXISTS patients (id TEXT PRIMARY KEY, village_id TEXT NOT NULL, age_band TEXT NOT NULL, sex TEXT NOT NULL, created REAL NOT NULL, FOREIGN KEY(village_id) REFERENCES villages(id));
CREATE TABLE IF NOT EXISTS screenings (id INTEGER PRIMARY KEY, client_key TEXT UNIQUE NOT NULL, patient_id TEXT NOT NULL, village_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('anaemia','oral')), consent INTEGER NOT NULL CHECK(consent=1), payload TEXT NOT NULL, triage TEXT NOT NULL DEFAULT '', created REAL NOT NULL, user_id INTEGER NOT NULL, demo INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS oral_screenings (screening_id INTEGER PRIMARY KEY, findings TEXT NOT NULL DEFAULT '[]', symptoms TEXT NOT NULL DEFAULT '[]', rules TEXT NOT NULL DEFAULT '[]', specialist_outcome TEXT, FOREIGN KEY(screening_id) REFERENCES screenings(id));
CREATE TABLE IF NOT EXISTS referrals (id INTEGER PRIMARY KEY, screening_id INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'issued', facility TEXT NOT NULL DEFAULT '', due_date TEXT, outcome TEXT, created REAL NOT NULL, updated REAL NOT NULL, FOREIGN KEY(screening_id) REFERENCES screenings(id));
CREATE TABLE IF NOT EXISTS follow_ups (id INTEGER PRIMARY KEY, patient_id TEXT NOT NULL, screening_id INTEGER, due_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'due', note TEXT NOT NULL DEFAULT '', created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS lab_results (id INTEGER PRIMARY KEY, screening_id INTEGER NOT NULL UNIQUE, hb REAL NOT NULL, confirmed INTEGER NOT NULL DEFAULT 1, created REAL NOT NULL, user_id INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS announcements (id INTEGER PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, translations TEXT NOT NULL DEFAULT '{}', village_id TEXT, scheduled_at TEXT, active INTEGER NOT NULL DEFAULT 1, created REAL NOT NULL, user_id INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS announcement_reads (announcement_id INTEGER NOT NULL, user_id INTEGER NOT NULL, read_at REAL NOT NULL, PRIMARY KEY(announcement_id,user_id));
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, updated REAL NOT NULL, user_id INTEGER);
CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY, user_id INTEGER, action TEXT NOT NULL, resource TEXT NOT NULL, created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS sync_receipts (client_key TEXT PRIMARY KEY, screening_id INTEGER NOT NULL, created REAL NOT NULL);
